package data

// The boss-skill preset data of PoB's src/Data/BossSkills.lua (`data.bossSkills`), which is
// itself machine-generated from the game data.
//
// CODE GENERATED BY oracle/boss_skills_emit.py FROM PoB 2.67.2-fixture. DO NOT EDIT.
// Regenerate with `task data-regen -- --only boss-skills` after a PoB pin bump.
//
// Its consumer is applyPresetBossSkills in calculator/configs.go, the port of
// ConfigOptions.lua:1637-1700.

// BossSkillValue is one OPTIONAL numeric field of a boss-skill row.
//
// ⚠️ IT EXISTS BECAUSE A GO ZERO IS NOT A LUA NIL. `critChance = 0` is declared on three presets
// and absent on five, and PoB does different things with the two: a declared 0 overwrites the
// enemyIsBoss default of 5, an absent one leaves that default standing. A bare float64 would
// silently turn every absent field into a declared zero.
//
// A pen carried as PoB's empty string (Maven Fireball's `DamagePenetrations = { FirePen = "" }`)
// also lands here as Set=false: `tonumber("")` is nil, so SetPlaceholder CLEARS the entry rather
// than writing a number.
type BossSkillValue struct {
	Value float64
	Set   bool
}

// BossSkill mirrors one row of `data.bossSkills`. `tooltip` is not carried -- it is UI text
// (ConfigOptions.lua:55) with no effect on any computed value -- but oracle/boss_skills.lua
// still declares it known, so a field PoB grows later trips the dumper's check.
//
// DamageMultipliers keeps PoB's unnamed pair: it indexes them as damageMult[1] and damageMult[2]
// at ConfigOptions.lua:1654 and :1656 and gives them no names of its own.
// BossSkillStat is one entry of `additionalStats`, which carries TWO KINDS OF VALUE and PoB
// discriminates on the literal string "flag": ConfigOptions.lua:2310-2314 makes a FLAG mod for
// "flag" and a BASE mod for anything else, both on the ENEMY mod list.
//
// ⚠️ A BARE float64 WOULD TURN EVERY `CannotBeBlocked = "flag"` INTO `BASE 0` -- a mod that
// exists, reads as configured, and does nothing. That is the silent-wrong-value shape, and it is
// worse than a missing mod because the config census would show the key present.
type BossSkillStat struct {
	Value  float64
	IsFlag bool
}

// BossSkillAdditionalStats is `additionalStats`, new in PoB 3.29. Base and Uber are INDEPENDENTLY
// optional -- Shaper Slam carries only `uber` -- so a nil map means "PoB has no entry for this
// difficulty", not "no stats".
type BossSkillAdditionalStats struct {
	Base map[string]BossSkillStat
	Uber map[string]BossSkillStat
}

type BossSkill struct {
	DamageType             string
	DamageMultipliers      map[string][2]float64
	UberDamageMultiplier   BossSkillValue
	DamagePenetrations     map[string]BossSkillValue
	UberDamagePenetrations map[string]BossSkillValue
	Speed                  BossSkillValue
	UberSpeed              BossSkillValue
	CritChance             BossSkillValue
	EarlierUber            bool
	AdditionalStats        *BossSkillAdditionalStats
}

